import React, { useEffect, useState } from "react";
import axios from "axios";

const CustomerDashboard = () => {
  const [listings, setListings] = useState([]);
  const [search, setSearch] = useState("");

  useEffect(() => {
    const fetchListings = async () => {
      try {
        const { data } = await axios.get("http://localhost:5000/api/listings");
        setListings(data);
      } catch (error) {
        console.error("Error fetching listings:", error);
      }
    };
    fetchListings();
  }, []);

  const filteredListings = listings.filter(
    (listing) =>
      listing.title?.toLowerCase().includes(search.toLowerCase()) ||
      listing.description?.toLowerCase().includes(search.toLowerCase())
  );

  const handleBuy = (listingId) => {
    alert(`Proceed to buy product with ID: ${listingId}`);
  };

  const handleContactSeller = (sellerEmail) => {
    if (!sellerEmail) {
      alert("Seller contact information not available.");
      return;
    }
    window.location.href = `mailto:${sellerEmail}`;
  };

  return (
    <div className="p-8 bg-gray-100 min-h-screen">
      <h1 className="text-4xl font-extrabold text-center text-gray-800 mb-10">
        🛍️ Explore All Listings
      </h1>

      {/* 🔍 Search Bar */}
      <div className="flex justify-center mb-10">
        <input
          type="text"
          placeholder="Search listings..."
          className="border border-gray-300 rounded-full px-5 py-3 w-2/3 sm:w-1/2 shadow-md focus:outline-none focus:ring-2 focus:ring-blue-500 transition"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      {/* 🏷️ Listings */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 px-4 sm:px-10">
        {filteredListings.length > 0 ? (
          filteredListings.map((listing) => (
            <div
              key={listing._id}
              className="bg-white shadow-xl rounded-2xl overflow-hidden hover:shadow-2xl transition transform hover:-translate-y-1"
            >
              <img
                src={
                  listing.image
                    ? `http://localhost:5000/${listing.image}`
                    : "/placeholder.jpg"
                }
                alt={listing.title}
                className="w-full h-52 object-cover"
              />

              <div className="p-5 flex flex-col justify-between h-full">
                <h2 className="text-2xl font-semibold text-gray-800 mb-2">
                  {listing.title}
                </h2>

                <p className="text-gray-600 mb-3 line-clamp-3">
                  {listing.description}
                </p>

                <p className="text-lg font-bold text-blue-700 mb-5">
                  ₹{listing.price || "N/A"}
                </p>

                {/* 🎯 Buttons Section */}
                <div className="flex justify-between space-x-3">
                  <button
                    onClick={() => handleBuy(listing._id)}
                    className="flex-1 bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 rounded-lg transition-all shadow-md"
                  >
                    Buy Now
                  </button>

                  <button
                    onClick={() => handleContactSeller(listing.sellerEmail)}
                    className="flex-1 bg-green-600 hover:bg-green-700 text-white font-semibold py-2 rounded-lg transition-all shadow-md"
                  >
                    Contact Seller
                  </button>
                </div>
              </div>
            </div>
          ))
        ) : (
          <p className="text-center text-gray-500 col-span-full text-lg">
            No listings found.
          </p>
        )}
      </div>
    </div>
  );
};

export default CustomerDashboard;
